#include <stdio.h>

int main() {
    /* 声明并初始化一个一维数组 */
    int arr[5] = {10, 20, 30, 40, 50};

    /* 遍历访问每个元素 */
    printf("数组元素: ");
    for (int i = 0; i < 5; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");  /* 输出: 数组元素: 10 20 30 40 50 */

    /* 通过索引直接访问，时间复杂度 O(1) */
    printf("arr[2] = %d\n", arr[2]);  /* 输出: 30 */

    return 0;
}

#include <stdio.h>

int main() {
    int num = 42;        /* 普通整型变量 */
    int *ptr = &num;   /* ptr 是指向 int 的指针，存储 num 的地址 */

    printf("num 的值: %d\n", num);           /* 输出: 42 */
    printf("num 的地址: %p\n", &num);      /* 输出: 0x16d2f2f38（示例地址） */
    printf("ptr 存储的地址: %p\n", ptr);    /* 输出: 同上 */
    printf("*ptr 解引用的值: %d\n", *ptr);  /* 输出: 42，* 为解引用运算符 */

    *ptr = 100;  /* 通过指针修改 num 的值 */
    printf("修改后 num = %d\n", num);        /* 输出: 100 */
    return 0;
}

