#include <stdio.h>
#include <stdlib.h>  /* malloc, free */

/* 链表节点结构体
   data：数据域，存储整型数据
   next：指针域，指向下一个同类型节点 */
struct Node {
    int data;
    struct Node* next;
};

/* 创建一个新节点
   参数 value: 节点的数据值
   返回值：指向新节点的指针，分配失败返回 NULL */
struct Node* createNode(int value) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    if (newNode == NULL) {
        printf("内存分配失败\n");
        return NULL;
    }
    newNode->data = value;   /* 设置数据 */
    newNode->next = NULL;    /* 新节点的 next 初始化为 NULL */
    return newNode;
}

#include <stdio.h>

/* 函数功能：计算数组元素之和
   时间复杂度：O(n)
   n 为数组长度，循环执行 n 次，每次循环执行常数次操作 */
int sumArray(int arr[], int n) {
    int total = 0;           /* O(1) — 赋值操作，执行 1 次 */
    for (int i = 0; i < n; i++) {  /* 循环体 */
        total += arr[i];    /* O(1) — 加法和赋值，执行 n 次 */
    }
    return total;            /* O(1) — 返回操作，执行 1 次 */
}
/* 整体时间复杂度：O(1 + n + 1) = O(n)
   低阶常数项被忽略 */

int main() {
    int nums[] = {5, 10, 15, 20, 25};
    int size = sizeof(nums) / sizeof(nums[0]);
    int result = sumArray(nums, size);
    printf("数组元素之和: %d\n", result);  /* 输出: 数组元素之和: 75 */
    return 0;
}
